import{_ as a}from"./chunks/paddingMode.Ca4E_CdM.js";import{_ as n,o as p,a as l,b as c}from"./app.C41L12d5.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"矩阵计算的搬入","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/cube_compute_load"},{"text":"DataCopyPad（GMToL1非对齐数据搬运）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/DataCopyPad_GMToL1"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/DataCopyPad_GMToL1.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/DataCopyPad_GMToL1.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),t={name:"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/DataCopyPad_GMToL1.md"};function d(o,s,e,i,r,m){return p(),l("div",null,[...s[0]||(s[0]=[c(`<div><article class="markdown-body"><h1>DataCopyPad（GMToL1非对齐数据搬运）</h1><h2 id="产品支持情况">产品支持情况<span id="section1550532418810"></span><a class="header-anchor" href="#产品支持情况">​</a></h2><p><span id="table38301303189"></span></p><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<span id="section618mcpsimp"></span><a class="header-anchor" href="#功能说明">​</a></h2><p>该接口提供从Global Memory到L1 Buffer的数据非对齐搬运功能，可以根据开发者的需要自行填充数据。</p><h2 id="函数原型">函数原型<span id="section620mcpsimp"></span><a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="p">,</span><span class="w"> </span><span class="n">PaddingMode</span><span class="w"> </span><span class="n">mode</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">PaddingMode</span><span class="o">::</span><span class="n">Normal</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">DataCopyPad</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">DataCopyExtParams</span><span class="o">&amp;</span><span class="w"> </span><span class="n">dataCopyParams</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">DataCopyPadExtParams</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">padParams</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<span id="section622mcpsimp"></span><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><p><span id="table4835205712588"></span></p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>操作数以及paddingValue（待填充数据值）的数据类型。</td></tr><tr><td>mode</td><td>配置数据搬运模式。PaddingMode类型，定义如下：<br>enum class PaddingMode : uint8_t {<br> Normal = 0, // 默认模式，与原有数据搬运格式保持一致，每次数据搬运都会补齐至32字节对齐<br> Compact, // 紧凑模式，允许单次搬运不对齐，统一在整块数据末尾补齐至32字节对齐<br>};</td></tr></tbody></table><p><strong>表 2</strong> 接口参数说明</p><p><span id="zh-cn_topic_0235751031_table33761356"></span></p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数，类型为LocalTensor。<br>LocalTensor的起始地址需要保证32字节对齐。</td></tr><tr><td>src</td><td>输入</td><td>源操作数，类型为GlobalTensor。<br>GlobalTensor的起始地址需要保证1字节对齐。</td></tr><tr><td>dataCopyParams</td><td>输入</td><td>搬运参数。<br>  • DataCopyExtParams类型，具体参数说明请参考<a href="#table10572141063919">表4</a>。</td></tr><tr><td>padParams</td><td>输入</td><td>从Global Memory搬运数据至Local Memory时，可以根据开发者需要，在搬运数据左边或右边填充数据。padParams是用于控制数据填充过程的参数。<br>  • DataCopyPadExtParams类型，具体参数请参考<a href="#table844881954715">表6</a>。</td></tr></tbody></table><p><strong>表 3</strong> DataCopyExtParams结构体参数定义</p><p><span id="table10572141063919"></span></p><table><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>blockCount</td><td>指定该指令包含的连续传输数据块个数，数据类型为uint16_t，取值范围：blockCount∈[1, 4095]。</td></tr><tr><td>blockLen</td><td>指定该指令每个连续传输数据块长度，<strong>该指令支持非对齐搬运</strong>，<strong>每个连续传输数据块长度单位为字节</strong>。数据类型为uint32_t，取值范围：blockLen∈[1, 2097151]，<strong>blockLen必须是sizeof(T)的整数倍</strong>。</td></tr><tr><td>srcStride</td><td>源操作数，相邻连续数据块的间隔（前面一个数据块的尾与后面数据块的头的间隔），单位为字节，取值范围为[-blockLen, 2^40-1]。</td></tr><tr><td>dstStride</td><td>目的操作数，相邻连续数据块间的间隔（前面一个数据块的尾与后面数据块的头的间隔），单位为dataBlock(32字节)，取值范围为[0, 65535]。</td></tr><tr><td>rsv</td><td>保留字段。</td></tr></tbody></table><p><strong>表 4</strong> DataCopyPadExtParams&lt;T&gt;结构体参数定义</p><p><span id="table844881954715"></span></p><table><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>isPad</td><td>是否需要填充用户自定义的数据，取值范围：true，false。<br>  • true：填充padding value。<br>  • false：表示用户不需要指定填充值，会默认填充随机值。</td></tr><tr><td>leftPadding</td><td>连续搬运数据块左侧需要补充的数据范围，单位为元素个数。<br><strong>leftPadding、rightPadding所占的字节数均不能超过32字节。</strong><br><strong>Compact模式下leftPadding、rightPadding均不生效，仅在整块数据末尾统一补齐至32字节对齐。</strong></td></tr><tr><td>rightPadding</td><td>连续搬运数据块右侧需要补充的数据范围，单位为元素个数。<br><strong>leftPadding、rightPadding所占的字节数均不能超过32字节。</strong><br><strong>Compact模式下leftPadding、rightPadding均不生效，仅在整块数据末尾统一补齐至32字节对齐。</strong></td></tr><tr><td>paddingValue</td><td>左右两侧需要填充的数据值，需要保证在数据占用字节范围内。<br>数据类型和源操作数保持一致，T数据类型。<br><strong>当数据类型长度为64位时，该参数只能设置为0。</strong></td></tr></tbody></table><p>下面给出如下场景的配置示例：</p><ul><li><span id="li1975762118172"></span>搬运模式的配置示例 <ul><li><p>Normal模式</p><p>blockLen为48，每个连续传输数据块包含48字节；srcStride为0，因为源操作数的逻辑位置为GM，srcStride的单位为字节，即源操作数相邻数据块之间紧密排列；dstStride为0，因为目的操作数的逻辑位置为L1 Buffer，dstStride的单位为DataBlock（32字节），目的操作数相邻数据块之间无间隔，注意数据块包含leftPadding/rightPadding数据。</p><p>blockLen + leftPadding + rightPadding满足32字节对齐，isPad为false，左右两侧填充的数据值会默认为随机值，否则为paddingValue。此处示例中，leftPadding为0，rightPadding为16，每个连续传输数据块都会在右侧填充16字节。目的操作数的总长度为192字节。</p></li><li><p>Compact模式</p><p>blockLen为48，每个连续传输数据块包含48字节；srcStride为0，因为源操作数的逻辑位置为GM，srcStride的单位为字节，即源操作数相邻数据块之间紧密排列；dstStride为0，因为目的操作数的逻辑位置为L1 Buffer，dstStride的单位为DataBlock（32字节），目的操作数相邻数据块之间紧密排列，不会填充数据。</p><p><strong>Compact模式下leftPadding、rightPadding均不生效</strong>，有效数据紧密排列后，统一在整块数据末尾补齐至32字节对齐。此处示例中，blockLen * blockCount = 48 * 3 = 144字节，在整块数据末尾补齐16字节满足32字节对齐，目的操作数的总长度为160字节。</p></li></ul></li></ul><p><strong>图 1</strong> Normal模式与Compact模式搬运配置示意图<a id="fig_paddingmode_demo"></a></p><p><img src="`+a+`" alt title="Normal模式与Compact模式搬运配置示意图"></p><h2 id="数据类型">数据类型<a class="header-anchor" href="#数据类型">​</a></h2><p>支持的数据类型为：bool、int8_t、uint8_t、int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float、complex32、int64_t、uint64_t、double、complex64。</p><h2 id="返回值说明">返回值说明<span id="section640mcpsimp"></span><a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<span id="section633mcpsimp"></span><a class="header-anchor" href="#约束说明">​</a></h2><ul><li>leftPadding、rightPadding的字节数均不能超过32字节。</li></ul><h2 id="调用示例">调用示例<span id="section177231425115410"></span><a class="header-anchor" href="#调用示例">​</a></h2><p>示例场景如<a href="#fig_paddingmode_demo">图 1</a>所示，该接口仅支持Ascend 950PR/Ascend 950DT。</p><p>Normal模式调用示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">srcElemCount</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">144</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">dstElemCount</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">192</span><span class="p">;</span>

<span class="c1">// 源操作数：GM上连续存放3个数据块，每块48B，共144个int8_t。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="kt">int8_t</span><span class="o">&gt;</span><span class="w"> </span><span class="n">srcGm</span><span class="p">;</span>
<span class="n">srcGm</span><span class="p">.</span><span class="n">SetGlobalBuffer</span><span class="p">((</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">int8_t</span><span class="w"> </span><span class="o">*</span><span class="p">)</span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="n">srcElemCount</span><span class="p">);</span>
<span class="c1">// 目的操作数：L1 Buffer。Normal模式下每块48B有效数据右侧补16B，3块共192B。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="kt">int8_t</span><span class="o">&gt;</span><span class="w"> </span><span class="n">dstLocal</span><span class="p">(</span><span class="n">AscendC</span><span class="o">::</span><span class="n">TPosition</span><span class="o">::</span><span class="n">A1</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="n">dstElemCount</span><span class="p">);</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopyExtParams</span><span class="w"> </span><span class="n">copyParams</span><span class="p">;</span>
<span class="c1">// 搬运3个连续传输数据块。</span>
<span class="n">copyParams</span><span class="p">.</span><span class="n">blockCount</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">3</span><span class="p">;</span>
<span class="c1">// 每个连续传输数据块包含48B有效数据。</span>
<span class="n">copyParams</span><span class="p">.</span><span class="n">blockLen</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">48</span><span class="p">;</span>
<span class="c1">// 源操作数在GM，单位为字节；相邻数据块紧密排列，间隔为0B。</span>
<span class="n">copyParams</span><span class="p">.</span><span class="n">srcStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="c1">// 目的端A1相邻数据块无额外间隔，dstStride的单位为DataBlock（32字节）。</span>
<span class="n">copyParams</span><span class="p">.</span><span class="n">dstStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="c1">// 保留字段，固定填0。</span>
<span class="n">copyParams</span><span class="p">.</span><span class="n">rsv</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopyPadExtParams</span><span class="o">&lt;</span><span class="kt">int8_t</span><span class="o">&gt;</span><span class="w"> </span><span class="n">padParams</span><span class="p">;</span>
<span class="c1">// padding区域使用默认随机值，不使用paddingValue。</span>
<span class="n">padParams</span><span class="p">.</span><span class="n">isPad</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">false</span><span class="p">;</span>
<span class="c1">// 左侧不填充，GM数据直接从每个目的数据块起始位置写入。</span>
<span class="n">padParams</span><span class="p">.</span><span class="n">leftPadding</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="c1">// 每块右侧填充16个int8_t，即16B；48B + 16B = 64B，满足32B对齐。</span>
<span class="n">padParams</span><span class="p">.</span><span class="n">rightPadding</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">16</span><span class="p">;</span>
<span class="c1">// isPad = false 时该值不生效，填0保持字段完整。</span>
<span class="n">padParams</span><span class="p">.</span><span class="n">paddingValue</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="k">static_cast</span><span class="o">&lt;</span><span class="kt">int8_t</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopyPad</span><span class="o">&lt;</span><span class="kt">int8_t</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">PaddingMode</span><span class="o">::</span><span class="n">Normal</span><span class="o">&gt;</span><span class="p">(</span><span class="n">dstLocal</span><span class="p">,</span><span class="w"> </span><span class="n">srcGm</span><span class="p">,</span><span class="w"> </span><span class="n">copyParams</span><span class="p">,</span><span class="w"> </span><span class="n">padParams</span><span class="p">);</span>
</code></pre></div><p>Compact模式调用示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">srcElemCount</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">144</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">dstElemCount</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">160</span><span class="p">;</span>

<span class="c1">// 源操作数：GM上连续存放3个数据块，每块48B，共144个int8_t。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="kt">int8_t</span><span class="o">&gt;</span><span class="w"> </span><span class="n">srcGm</span><span class="p">;</span>
<span class="n">srcGm</span><span class="p">.</span><span class="n">SetGlobalBuffer</span><span class="p">((</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">int8_t</span><span class="w"> </span><span class="o">*</span><span class="p">)</span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="n">srcElemCount</span><span class="p">);</span>

<span class="c1">// 目的操作数：L1 Buffer的A1位置。Compact模式下3块有效数据共144B，只在最后右侧补16B。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="kt">int8_t</span><span class="o">&gt;</span><span class="w"> </span><span class="n">dstLocal</span><span class="p">(</span><span class="n">AscendC</span><span class="o">::</span><span class="n">TPosition</span><span class="o">::</span><span class="n">A1</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="n">dstElemCount</span><span class="p">);</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopyExtParams</span><span class="w"> </span><span class="n">copyParams</span><span class="p">;</span>
<span class="c1">// 搬运3个连续传输数据块。</span>
<span class="n">copyParams</span><span class="p">.</span><span class="n">blockCount</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">3</span><span class="p">;</span>
<span class="c1">// 每个连续传输数据块包含48B有效数据。</span>
<span class="n">copyParams</span><span class="p">.</span><span class="n">blockLen</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">48</span><span class="p">;</span>
<span class="c1">// 源操作数在GM，单位为字节；相邻数据块紧密排列，间隔为0B。</span>
<span class="n">copyParams</span><span class="p">.</span><span class="n">srcStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="c1">// Compact模式下目的端有效数据紧密排列，不在每块之间插入padding间隔。</span>
<span class="n">copyParams</span><span class="p">.</span><span class="n">dstStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="c1">// 保留字段，固定填0。</span>
<span class="n">copyParams</span><span class="p">.</span><span class="n">rsv</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopyPadExtParams</span><span class="o">&lt;</span><span class="kt">int8_t</span><span class="o">&gt;</span><span class="w"> </span><span class="n">padParams</span><span class="p">;</span>
<span class="c1">// padding区域使用默认随机值，不使用paddingValue。</span>
<span class="n">padParams</span><span class="p">.</span><span class="n">isPad</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">false</span><span class="p">;</span>
<span class="c1">// isPad = false时该值不生效，填0保持字段完整。</span>
<span class="n">padParams</span><span class="p">.</span><span class="n">paddingValue</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="k">static_cast</span><span class="o">&lt;</span><span class="kt">int8_t</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopyPad</span><span class="o">&lt;</span><span class="kt">int8_t</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">PaddingMode</span><span class="o">::</span><span class="n">Compact</span><span class="o">&gt;</span><span class="p">(</span><span class="n">dstLocal</span><span class="p">,</span><span class="w"> </span><span class="n">srcGm</span><span class="p">,</span><span class="w"> </span><span class="n">copyParams</span><span class="p">,</span><span class="w"> </span><span class="n">padParams</span><span class="p">);</span>
</code></pre></div></article></div>`,1)])])}const b=n(t,[["render",d]]);export{_ as __pageData,b as default};
